import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, mix, vec3, uniform, smoothstep, clamp } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color, DoubleSide, Texture } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'pricing-card-2-label';

  // --- Atlas-derived aspect ratio (512x320 source rect) ---
  const rectW = 512;
  const rectH = 320;
  const aspect = rectW / rectH;
  const width = 1.2;
  const height = width / aspect;

  // --- Engineered gradient plate (ink -> surface) with grain texture + accent hairline ---
  const geometry = new PlaneGeometry(width, height, 1, 1);

  const inkColor = uniform(vec3(new Color(colors.ink)));
  const surfaceColor = uniform(vec3(new Color(colors.surface)));
  const accentColor = uniform(vec3(new Color(colors.accent)));

  const grainTex = new Texture();
  const grainNode = texture(grainTex);

  const gradient = mix(inkColor, surfaceColor, clamp(uv().y, 0.0, 1.0));
  // subtle grain modulation (kept low-amplitude so it never washes out the plate)
  const grained = gradient.add(grainNode.r.sub(0.5).mul(0.05));

  // thin accent hairline along the bottom edge (<=10% of the plate area)
  const edgeMask = smoothstep(0.0, 0.02, uv().y).oneMinus().mul(smoothstep(0.0, 0.03, uv().y));
  const withAccent = mix(grained, accentColor, edgeMask.mul(0.9));

  const material = new MeshBasicNodeMaterial({ side: DoubleSide, transparent: false });
  material.colorNode = withAccent;

  const plate = new Mesh(geometry, material);
  plate.position.set(0, 0, 0);
  root.add(plate);

  // load grain texture and swap it into the node graph once ready
  let disposed = false;
  ctx.textureLoader
    .loadTexture(config.imageUrl ?? '/prism-assets/chrome/ceramic-grain.map.png')
    .then((tex) => {
      if (disposed) return;
      tex.wrapS = THREE.RepeatWrapping;
      tex.wrapT = THREE.RepeatWrapping;
      grainNode.value = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      /* texture optional — gradient still reads correctly without grain */
    });

  // --- Headline label text: "Pricing 2" ---
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [{ text: 'Pricing 2', role: 'headline', typography: { fontSize: 39 } }];
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const fontSize = headlineItem?.typography?.fontSize ?? 39;

  const textNode = ctx.fontAtlas.createText(headlineItem?.text ?? 'Pricing 2', {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, height * 0.06, 0.012);
  root.add(textNode);

  // --- Motion: weighted entrance + capped idle breathing ---
  root.scale.setScalar(0.001);
  const tl = gsap.timeline();
  tl.to(root.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power3.out' }).to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.5, ease: 'power4.out' },
    '-=0.1'
  );

  const breathe = gsap.to(plate.scale, {
    x: 1.015,
    y: 1.015,
    duration: 2.6,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1,
  });

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    breathe.kill();
    geometry.dispose();
    material.dispose();
    if (grainNode.value && grainNode.value.dispose) grainNode.value.dispose();
    if (textNode.userData?.cleanup) textNode.userData.cleanup();
  };

  return root;
}
